rng=np.random.default_rng(2)
def fit(f,n,tries=80):
    best=None
    for _ in range(tries):
        p0=rng.normal(0,1,n)
        try:
            with np.errstate(all='ignore'):
                s=least_squares(lambda p: np.nan_to_num(f(p)-dA_dt,nan=1e3,posinf=1e3,neginf=-1e3),p0,max_nfev=2000)
            if np.isfinite(s.cost) and (best is None or s.cost<best.cost): best=s
        except Exception: pass
    return best
